  for matcher in route.get('matchers',[]):
   key,op,raw=re.fullmatch(r'\s*([A-Za-z_][A-Za-z0-9_]*)\s*(=~|!~|!=|=)\s*(".*")\s*',matcher).groups();value=json.loads(raw);actual=labels.get(key,'');hit=bool(re.fullmatch(value,actual))if op in ['=~','!~']else actual==value
   if hit!=(op not in ['!=','!~']):return False
  return True
 def walk(route,path):
  selected=[]
  for index,child in enumerate(route.get('routes',[])):
   if matches(child):
    selected+=walk(child,path+'/routes/'+str(index))
    if not child.get('continue',False):break
  return selected or[path]
 return walk(config['route'],'/route')

